package com.oveduumnakal.charactersnapshot;

import java.io.File;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;

import com.google.gson.Gson;
import com.google.inject.Provides;
import com.oveduumnakal.charactersnapshot.model.CharacterSnapshot;
import lombok.extern.slf4j.Slf4j;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GrandExchangeOfferChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.RuneLite;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

/**
 * Writes a live snapshot of the logged-in character to a local JSON file for external tools. State is
 * collected on the client thread from events and periodic polling, and written off-thread. The plugin
 * makes no network calls of any kind.
 */
@Slf4j
@PluginDescriptor(
	name = "Character Snapshot",
	description = "Saves a live snapshot of your character to a local JSON file for external tools",
	tags = {"snapshot", "live", "state", "character", "data", "json", "local"}
)
public class CharacterSnapshotPlugin extends Plugin
{
	private static final int INITIAL_DELAY_TICKS = 10;

	private static final int POLL_INTERVAL_TICKS = 30;

	@Inject
	private Client client;

	@Inject
	private CharacterSnapshotConfig config;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private Gson gson;

	private SnapshotCollector collector;

	private SnapshotWriter writer;

	private volatile boolean dirty = false;

	private int tickCounter = 0;

	private int syncTickThreshold = 100;

	private boolean initialCollectionDone = false;

	private String lastPlayerName = null;

	/**
	 * Initializes the collector and writer and computes the save interval.
	 */
	@Override
	protected void startUp()
	{
		collector = new SnapshotCollector(client, config);
		writer = new SnapshotWriter(gson);
		recalcSyncThreshold();
	}

	/**
	 * Writes a final snapshot when still logged in, then releases resources.
	 */
	@Override
	protected void shutDown()
	{
		if (client.getGameState() == GameState.LOGGED_IN)
			doSave();

		collector = null;
		writer = null;
	}

	/**
	 * Provides the plugin configuration.
	 *
	 * @param configManager the config manager
	 * @return the bound configuration
	 */
	@Provides
	CharacterSnapshotConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CharacterSnapshotConfig.class);
	}

	/**
	 * Recomputes the save interval when this plugin's configuration changes.
	 *
	 * @param event the config-changed event
	 */
	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (CharacterSnapshotConfig.GROUP.equals(event.getGroup()))
			recalcSyncThreshold();
	}

	/**
	 * Schedules the initial collection on login and clears state on logout or world hop so one
	 * character's data cannot leak into another's file. The initial collection restores the
	 * character's own last known items from its previous export.
	 *
	 * @param event the game-state event
	 */
	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGGED_IN)
		{
			tickCounter = -INITIAL_DELAY_TICKS;
			initialCollectionDone = false;
		}
		else if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			doSave();
			if (collector != null)
				collector.reset();

			initialCollectionDone = false;
		}
	}

	/**
	 * Caches a changed skill (real, experience, and boosted levels).
	 *
	 * @param event the stat-changed event
	 */
	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (collector == null || !config.syncSkills())
			return;

		collector.updateSkill(event.getSkill(), event.getLevel(), event.getXp(), event.getBoostedLevel());
		dirty = true;
	}

	/**
	 * Caches bank, inventory, or equipment changes.
	 *
	 * @param event the container-changed event
	 */
	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (collector == null)
			return;

		int id = event.getContainerId();
		if (id == InventoryID.BANK && config.syncBank())
		{
			collector.updateBank(event.getItemContainer());
			dirty = true;
		}
		else if (id == InventoryID.INV && config.syncInventory())
		{
			collector.updateInventory(event.getItemContainer());
			dirty = true;
		}
		else if (id == InventoryID.WORN && config.syncEquipment())
		{
			collector.updateEquipment(event.getItemContainer());
			dirty = true;
		}
	}

	/**
	 * Caches a changed Grand Exchange offer.
	 *
	 * @param event the offer-changed event
	 */
	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
	{
		if (collector == null || !config.syncGrandExchange())
			return;

		collector.updateGeOffer(event.getSlot(), event.getOffer());
		dirty = true;
	}

	/**
	 * Drives the initial collection, periodic polling, and interval-gated saves.
	 *
	 * @param event the game-tick event
	 */
	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (client.getGameState() != GameState.LOGGED_IN || collector == null)
			return;

		Player local = client.getLocalPlayer();
		if (local == null)
			return;

		String currentName = local.getName();
		if (initialCollectionDone && currentName != null && !currentName.equals(lastPlayerName))
		{
			collector.reset();
			initialCollectionDone = false;
			tickCounter = 0;
		}

		tickCounter++;

		if (!initialCollectionDone && tickCounter >= 0)
		{
			collector.restore(writer.read(currentName, resolveSyncDir()));
			doFullCollection();
			lastPlayerName = currentName;
			initialCollectionDone = true;
			dirty = true;
			doSave();
			return;
		}

		if (tickCounter % POLL_INTERVAL_TICKS == 0)
			pollPeriodic();

		if (dirty && tickCounter >= syncTickThreshold)
		{
			tickCounter = 0;
			doSave();
		}
	}

	/**
	 * Polls the data sources that are not event-driven, marking the snapshot dirty on any change.
	 */
	private void pollPeriodic()
	{
		boolean changed = false;
		if (config.syncQuests())
			changed |= collector.pollQuests();

		if (config.syncDiaries())
			changed |= collector.pollDiaries();

		if (config.syncCombatAchievements())
			changed |= collector.pollCombatAchievements();

		if (config.syncSlayer())
			changed |= collector.pollSlayer();

		if (changed)
			dirty = true;
	}

	/**
	 * Runs a one-off full collection of every enabled data source after login.
	 */
	private void doFullCollection()
	{
		if (config.syncSkills())
			collector.pollAllSkills();

		if (config.syncBank())
		{
			ItemContainer bank = client.getItemContainer(InventoryID.BANK);
			if (bank != null)
				collector.updateBank(bank);
		}

		if (config.syncInventory())
		{
			ItemContainer inv = client.getItemContainer(InventoryID.INV);
			if (inv != null)
				collector.updateInventory(inv);
		}

		if (config.syncEquipment())
		{
			ItemContainer equip = client.getItemContainer(InventoryID.WORN);
			if (equip != null)
				collector.updateEquipment(equip);
		}

		if (config.syncQuests())
			collector.pollQuests();

		if (config.syncDiaries())
			collector.pollDiaries();

		if (config.syncCombatAchievements())
			collector.pollCombatAchievements();

		if (config.syncSlayer())
			collector.pollSlayer();

		if (config.syncGrandExchange())
			collector.pollAllGeOffers();
	}

	/**
	 * Builds a snapshot on the client thread and writes it off-thread. Clears the dirty flag
	 * optimistically and re-sets it if the write fails, so a failed write is retried.
	 */
	private void doSave()
	{
		if (collector == null || writer == null || !dirty)
			return;

		CharacterSnapshot snapshot = collector.buildSnapshot();
		if (snapshot == null)
			return;

		dirty = false;
		File dir = resolveSyncDir();
		executor.submit(() ->
		{
			if (!writer.write(snapshot, dir))
				dirty = true;
		});
	}

	/**
	 * Resolves the export directory: the configured folder if set, else the default under the
	 * RuneLite directory.
	 *
	 * @return the directory to write export files into
	 */
	private File resolveSyncDir()
	{
		String custom = config.saveDirectory();
		if (custom != null && !custom.trim().isEmpty())
			return new File(custom.trim());

		return new File(RuneLite.RUNELITE_DIR, "osrs-companion");
	}

	/**
	 * Recomputes the save threshold in game ticks (one tick is about 0.6 seconds).
	 */
	private void recalcSyncThreshold()
	{
		int seconds = Math.max(30, config.syncIntervalSeconds());
		syncTickThreshold = (int) (seconds / 0.6);
	}
}

package docs;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;

/**
 * Command-line driver for the JavaDocs.md generator and freshness gate.
 *
 * <p>This lives in a standalone Gradle build ({@code javadoc-tools}) invoked only by CI and
 * developers, so the third-party javaparser dependency never enters the plugin build the
 * RuneLite plugin-hub compiles (which runs under dependency verification). Usage:</p>
 *
 * <pre>
 * generate &lt;sourceRoot&gt; &lt;outputFile&gt;
 * check    &lt;sourceRoot&gt; &lt;outputFile&gt; [--exclude-overrides]
 * </pre>
 */
public final class JavaDocsCli {

	private static final int DIFF_PREVIEW_LINES = 20;

	private JavaDocsCli() {
	}

	/**
	 * Runs the {@code generate} or {@code check} subcommand.
	 *
	 * @param args the subcommand, source root, output file, and optional {@code --exclude-overrides}
	 */
	public static void main(String[] args) {
		if (args.length < 3) {
			System.err.println("usage: (generate|check) <sourceRoot> <outputFile> [--exclude-overrides]");
			System.exit(2);
			return;
		}
		String command = args[0];
		Path sourceRoot = Paths.get(args[1]);
		Path output = Paths.get(args[2]);
		boolean excludeOverrides = false;
		for (int i = 3; i < args.length; i++) {
			if ("--exclude-overrides".equals(args[i])) {
				excludeOverrides = true;
			}
		}
		if ("generate".equals(command)) {
			generate(sourceRoot, output);
		}
		else if ("check".equals(command)) {
			check(sourceRoot, output, excludeOverrides);
		}
		else {
			System.err.println("unknown command: " + command);
			System.exit(2);
		}
	}

	/**
	 * Scans, renders, and writes the Markdown file as UTF-8 with LF line endings.
	 *
	 * @param sourceRoot the {@code src/main/java} directory to scan
	 * @param output the {@code JavaDocs.md} file to write
	 */
	private static void generate(Path sourceRoot, Path output) {
		List<JavaDocModel.TypeDoc> types = new JavaDocScanner(sourceRoot).scan();
		String markdown = new MarkdownRenderer().render(types);
		try {
			Files.write(output, markdown.getBytes(StandardCharsets.UTF_8));
		}
		catch (IOException e) {
			throw new UncheckedIOException("Failed to write " + output, e);
		}
		System.out.println("Wrote " + output + " (" + types.size() + " types)");
	}

	/**
	 * Runs the drift and coverage checks and exits non-zero if either reports a problem.
	 *
	 * @param sourceRoot the {@code src/main/java} directory to scan
	 * @param output the committed {@code JavaDocs.md} to compare against
	 * @param excludeOverrides whether {@code @Override} methods are exempt from the coverage requirement
	 */
	private static void check(Path sourceRoot, Path output, boolean excludeOverrides) {
		List<JavaDocModel.TypeDoc> types = new JavaDocScanner(sourceRoot).scan();
		List<String> failures = new ArrayList<>();
		checkDrift(types, output, failures);
		checkCoverage(types, excludeOverrides, failures);
		if (!failures.isEmpty()) {
			System.err.println(String.join("\n\n", failures));
			System.exit(1);
			return;
		}
		System.out.println("JavaDocs.md is fresh and all public/protected members are documented.");
	}

	/**
	 * Compares freshly rendered Markdown against the committed file byte-for-byte.
	 *
	 * @param types the scanned type records
	 * @param output the committed {@code JavaDocs.md}
	 * @param failures the accumulating failure-message list
	 */
	private static void checkDrift(List<JavaDocModel.TypeDoc> types, Path output, List<String> failures) {
		String expected = new MarkdownRenderer().render(types);
		if (!Files.exists(output)) {
			failures.add("JavaDocs.md is missing. Run ./gradlew generateJavaDocs and commit the result.");
			return;
		}
		String actual = readLf(output);
		if (!expected.equals(actual)) {
			StringBuilder message = new StringBuilder(
					"JavaDocs.md is out of date. Run ./gradlew generateJavaDocs and commit the result.");
			message.append("\n").append(firstDiff(expected, actual));
			failures.add(message.toString());
		}
	}

	/**
	 * Runs the coverage checker and records any offenders.
	 *
	 * @param types the scanned type records
	 * @param excludeOverrides whether {@code @Override} methods are exempt
	 * @param failures the accumulating failure-message list
	 */
	private static void checkCoverage(List<JavaDocModel.TypeDoc> types, boolean excludeOverrides,
			List<String> failures) {
		List<String> offenders = new CoverageChecker(excludeOverrides).findOffenders(types);
		if (!offenders.isEmpty()) {
			StringBuilder message = new StringBuilder(
					"The following public/protected declarations are missing Javadoc:");
			for (String offender : offenders) {
				message.append("\n  ").append(offender);
			}
			failures.add(message.toString());
		}
	}

	/**
	 * Reads a file as UTF-8, normalizing line endings to LF for comparison.
	 *
	 * @param path the file to read
	 * @return the file content with {@code \n} line endings
	 */
	private static String readLf(Path path) {
		try {
			String content = new String(Files.readAllBytes(path), StandardCharsets.UTF_8);
			return content.replace("\r\n", "\n").replace("\r", "\n");
		}
		catch (IOException e) {
			throw new UncheckedIOException("Failed to read " + path, e);
		}
	}

	/**
	 * Builds a short preview of the first differing lines to aid debugging.
	 *
	 * @param expected the freshly rendered content
	 * @param actual the committed content
	 * @return a unified-style preview of the first divergence
	 */
	private static String firstDiff(String expected, String actual) {
		String[] expectedLines = expected.split("\n", -1);
		String[] actualLines = actual.split("\n", -1);
		int max = Math.max(expectedLines.length, actualLines.length);
		StringBuilder preview = new StringBuilder("First difference:");
		int shown = 0;
		for (int i = 0; i < max && shown < DIFF_PREVIEW_LINES; i++) {
			String expectedLine = i < expectedLines.length ? expectedLines[i] : "<end of file>";
			String actualLine = i < actualLines.length ? actualLines[i] : "<end of file>";
			if (!expectedLine.equals(actualLine)) {
				preview.append("\n  line ").append(i + 1);
				preview.append("\n  - committed: ").append(actualLine);
				preview.append("\n  + expected:  ").append(expectedLine);
				shown++;
			}
		}
		return preview.toString();
	}
}

package docs;

import com.github.javaparser.javadoc.Javadoc;
import com.github.javaparser.javadoc.JavadocBlockTag;
import java.util.Comparator;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

/**
 * Renders a sorted {@link JavaDocModel.TypeDoc} list into the single {@code JavaDocs.md} string.
 *
 * <p>The layout mirrors a generated Javadoc page: each type shows Summary tables
 * (nested types, enum constants, fields, constructors, methods) followed by Detail
 * sections. Output is deterministic — types and members are sorted by stable keys,
 * inline tags are converted uniformly, line endings are {@code \n}, and there is a
 * single trailing newline. No timestamps, paths, or version strings appear.</p>
 */
public final class MarkdownRenderer {

	private static final String TITLE = "# Stockpile — JavaDoc Reference";

	private static final Pattern INLINE_TAG =
			Pattern.compile("\\{@(code|literal|link|linkplain)\\s+([^}]*)}");

	private static final Pattern HTML_TAG = Pattern.compile("<[^>]+>");

	private static final Comparator<JavaDocModel.TypeDoc> TYPE_ORDER =
			Comparator.comparing((JavaDocModel.TypeDoc t) -> t.packageName())
					.thenComparing(JavaDocModel.TypeDoc::qualifiedName);

	private static final Comparator<JavaDocModel.MemberDoc> MEMBER_ORDER =
			Comparator.comparing((JavaDocModel.MemberDoc m) -> m.name())
					.thenComparing(m -> String.join(",", m.paramTypeSimpleNames()));

	/**
	 * Renders the full document.
	 *
	 * @param types the collected type records (any order; sorted internally)
	 * @return the complete Markdown document, ending in exactly one newline
	 */
	public String render(List<JavaDocModel.TypeDoc> types) {
		List<JavaDocModel.TypeDoc> sorted = types.stream()
				.sorted(TYPE_ORDER)
				.collect(Collectors.toList());
		StringBuilder sb = new StringBuilder();
		sb.append(TITLE).append("\n\n");
		sb.append("<!-- GENERATED FILE — DO NOT EDIT BY HAND.\n");
		sb.append("     Run `./gradlew generateJavaDocs` and commit the result. -->\n\n");
		sb.append("## Contents\n\n");
		for (JavaDocModel.TypeDoc type : sorted) {
			sb.append("- [")
					.append(type.qualifiedName())
					.append("](#")
					.append(slug(type.qualifiedName()))
					.append(")\n");
		}
		sb.append("\n");
		for (JavaDocModel.TypeDoc type : sorted) {
			sb.append("---\n\n");
			renderType(sb, type, sorted);
		}
		return normalizeTrailing(sb.toString());
	}

	/**
	 * Renders a single type section: header, summaries, then details.
	 *
	 * @param sb the output buffer
	 * @param type the type record
	 * @param allTypes the full sorted type list, used to find nested types
	 */
	private void renderType(StringBuilder sb, JavaDocModel.TypeDoc type, List<JavaDocModel.TypeDoc> allTypes) {
		sb.append("## ").append(type.qualifiedName()).append("\n\n");
		sb.append("_").append(type.kind().label()).append("_\n\n");
		sb.append("`").append(type.signature()).append("`\n\n");
		type.javadoc().ifPresent(doc -> appendDescription(sb, doc));
		type.javadoc().ifPresent(doc -> appendTypeTags(sb, doc));

		List<JavaDocModel.TypeDoc> nested = nestedTypes(type, allTypes);
		List<JavaDocModel.MemberDoc> enumConstants = membersOfKind(
				type.fields(), JavaDocModel.MemberKind.ENUM_CONSTANT);
		List<JavaDocModel.MemberDoc> fields = membersOfKind(
				type.fields(), JavaDocModel.MemberKind.FIELD);
		List<JavaDocModel.MemberDoc> constructors = sortMembers(type.constructors());
		List<JavaDocModel.MemberDoc> methods = sortMembers(type.methods());

		renderNestedSummary(sb, nested);
		renderMemberSummary(sb, "Enum Constant Summary", "Enum Constant", enumConstants, false);
		renderMemberSummary(sb, "Field Summary", "Field", fields, true);
		renderMemberSummary(sb, "Constructor Summary", "Constructor", constructors, false);
		renderMemberSummary(sb, "Method Summary", "Method", methods, true);

		renderMemberDetail(sb, "Enum Constant Detail", enumConstants);
		renderMemberDetail(sb, "Field Detail", fields);
		renderMemberDetail(sb, "Constructor Detail", constructors);
		renderMemberDetail(sb, "Method Detail", methods);
	}

	/**
	 * Renders the nested-type summary table, if the type has nested types.
	 *
	 * @param sb the output buffer
	 * @param nested the direct nested types, already sorted
	 */
	private void renderNestedSummary(StringBuilder sb, List<JavaDocModel.TypeDoc> nested) {
		if (nested.isEmpty()) {
			return;
		}
		sb.append("### Nested Type Summary\n\n");
		sb.append("| Type | Description |\n");
		sb.append("|---|---|\n");
		for (JavaDocModel.TypeDoc child : nested) {
			sb.append("| _").append(child.kind().label()).append("_ [`")
					.append(child.simpleName()).append("`](#")
					.append(slug(child.qualifiedName())).append(") | ")
					.append(summaryText(child.javadoc())).append(" |\n");
		}
		sb.append("\n");
	}

	/**
	 * Renders one member summary table, if the group is non-empty.
	 *
	 * @param sb the output buffer
	 * @param heading the section heading (e.g. {@code Method Summary})
	 * @param memberColumn the header for the declaration column
	 * @param members the group's members, already sorted
	 * @param withType whether to include a leading {@code Modifier and Type} column
	 */
	private void renderMemberSummary(
			StringBuilder sb,
			String heading,
			String memberColumn,
			List<JavaDocModel.MemberDoc> members,
			boolean withType) {
		if (members.isEmpty()) {
			return;
		}
		sb.append("### ").append(heading).append("\n\n");
		if (withType) {
			sb.append("| Modifier and Type | ").append(memberColumn).append(" | Description |\n");
			sb.append("|---|---|---|\n");
		}
		else {
			sb.append("| ").append(memberColumn).append(" | Description |\n");
			sb.append("|---|---|\n");
		}
		for (JavaDocModel.MemberDoc member : members) {
			sb.append("| ");
			if (withType) {
				sb.append(cellCode(member.modifierAndType())).append(" | ");
			}
			sb.append(cellCode(member.declaration())).append(" | ")
					.append(summaryText(member.javadoc())).append(" |\n");
		}
		sb.append("\n");
	}

	/**
	 * Renders one member detail section, if the group is non-empty.
	 *
	 * @param sb the output buffer
	 * @param heading the section heading (e.g. {@code Method Detail})
	 * @param members the group's members, already sorted
	 */
	private void renderMemberDetail(StringBuilder sb, String heading, List<JavaDocModel.MemberDoc> members) {
		if (members.isEmpty()) {
			return;
		}
		sb.append("### ").append(heading).append("\n\n");
		for (JavaDocModel.MemberDoc member : members) {
			sb.append("#### ").append(member.name()).append("\n\n");
			sb.append("`").append(member.signature()).append("`\n\n");
			member.javadoc().ifPresent(doc -> appendDescription(sb, doc));
			member.javadoc().ifPresent(doc -> appendMemberTags(sb, doc));
		}
	}

	/**
	 * Finds the direct nested types of a type from the full sorted list.
	 *
	 * @param type the enclosing type
	 * @param allTypes the full sorted type list
	 * @return the direct nested types, in sorted order
	 */
	private List<JavaDocModel.TypeDoc> nestedTypes(
			JavaDocModel.TypeDoc type,
			List<JavaDocModel.TypeDoc> allTypes) {
		String prefix = type.qualifiedName() + ".";
		return allTypes.stream()
				.filter(t -> t.qualifiedName().startsWith(prefix))
				.filter(t -> t.qualifiedName().indexOf('.', prefix.length()) < 0)
				.collect(Collectors.toList());
	}

	/**
	 * Filters a member list to a single kind, sorted by the stable member order.
	 *
	 * @param members the members to filter
	 * @param kind the kind to keep
	 * @return the matching members, sorted
	 */
	private List<JavaDocModel.MemberDoc> membersOfKind(
			List<JavaDocModel.MemberDoc> members,
			JavaDocModel.MemberKind kind) {
		return members.stream()
				.filter(m -> m.kind() == kind)
				.sorted(MEMBER_ORDER)
				.collect(Collectors.toList());
	}

	/**
	 * Sorts a member list by the stable member order.
	 *
	 * @param members the members to sort
	 * @return the sorted members
	 */
	private List<JavaDocModel.MemberDoc> sortMembers(List<JavaDocModel.MemberDoc> members) {
		return members.stream()
				.sorted(MEMBER_ORDER)
				.collect(Collectors.toList());
	}

	/**
	 * Appends a Javadoc description body, if it has visible text.
	 *
	 * @param sb the output buffer
	 * @param doc the parsed Javadoc
	 */
	private void appendDescription(StringBuilder sb, Javadoc doc) {
		String body = convertInlineTags(doc.getDescription().toText()).trim();
		if (!body.isEmpty()) {
			sb.append(body).append("\n\n");
		}
	}

	/**
	 * Appends type-level block tags as paragraph lines (Deprecated, See, and others).
	 *
	 * @param sb the output buffer
	 * @param doc the parsed Javadoc
	 */
	private void appendTypeTags(StringBuilder sb, Javadoc doc) {
		for (JavadocBlockTag tag : doc.getBlockTags()) {
			String content = convertInlineTags(tag.getContent().toText()).trim();
			String name = tag.getName().orElse("");
			StringBuilder line = new StringBuilder();
			line.append("**").append(typeTagLabel(tag)).append(":**");
			if (!name.isEmpty()) {
				line.append(" `").append(name).append("`");
			}
			if (!content.isEmpty()) {
				line.append(name.isEmpty() ? " " : " — ").append(content);
			}
			sb.append(line).append("\n\n");
		}
	}

	/**
	 * Appends member-level block tags grouped as Parameters, Returns, Throws, then extras.
	 *
	 * @param sb the output buffer
	 * @param doc the parsed Javadoc
	 */
	private void appendMemberTags(StringBuilder sb, Javadoc doc) {
		boolean any = false;
		for (JavadocBlockTag tag : doc.getBlockTags()) {
			if (tag.getType() == JavadocBlockTag.Type.PARAM) {
				sb.append("- **Parameter** `").append(tag.getName().orElse("")).append("`");
				appendDash(sb, tagContent(tag));
				sb.append("\n");
				any = true;
			}
		}
		for (JavadocBlockTag tag : doc.getBlockTags()) {
			if (tag.getType() == JavadocBlockTag.Type.RETURN) {
				sb.append("- **Returns:**");
				appendSpace(sb, tagContent(tag));
				sb.append("\n");
				any = true;
			}
		}
		for (JavadocBlockTag tag : doc.getBlockTags()) {
			if (tag.getType() == JavadocBlockTag.Type.THROWS
					|| tag.getType() == JavadocBlockTag.Type.EXCEPTION) {
				sb.append("- **Throws** `").append(tag.getName().orElse("")).append("`");
				appendDash(sb, tagContent(tag));
				sb.append("\n");
				any = true;
			}
		}
		for (JavadocBlockTag tag : doc.getBlockTags()) {
			if (isExtraMemberTag(tag)) {
				sb.append("- **").append(capitalize(tag.getTagName())).append(":**");
				appendSpace(sb, tagContent(tag));
				sb.append("\n");
				any = true;
			}
		}
		if (any) {
			sb.append("\n");
		}
	}

	/**
	 * Reports whether a member tag is neither a parameter, return, nor throws tag.
	 *
	 * @param tag the block tag
	 * @return {@code true} if the tag is rendered in the generic extras group
	 */
	private boolean isExtraMemberTag(JavadocBlockTag tag) {
		JavadocBlockTag.Type type = tag.getType();
		return type != JavadocBlockTag.Type.PARAM
				&& type != JavadocBlockTag.Type.RETURN
				&& type != JavadocBlockTag.Type.THROWS
				&& type != JavadocBlockTag.Type.EXCEPTION;
	}

	/**
	 * Returns a block tag's content with inline tags converted and edges trimmed.
	 *
	 * @param tag the block tag
	 * @return the cleaned content text
	 */
	private String tagContent(JavadocBlockTag tag) {
		return convertInlineTags(tag.getContent().toText()).trim();
	}

	/**
	 * Appends {@code  — content} when content is present, nothing otherwise.
	 *
	 * @param sb the output buffer
	 * @param content the trimmed content text
	 */
	private void appendDash(StringBuilder sb, String content) {
		if (!content.isEmpty()) {
			sb.append(" — ").append(content);
		}
	}

	/**
	 * Appends {@code  content} when content is present, nothing otherwise.
	 *
	 * @param sb the output buffer
	 * @param content the trimmed content text
	 */
	private void appendSpace(StringBuilder sb, String content) {
		if (!content.isEmpty()) {
			sb.append(" ").append(content);
		}
	}

	/**
	 * Chooses the display label for a type-level block tag.
	 *
	 * @param tag the block tag
	 * @return the label (e.g. {@code Deprecated}, {@code See}, or the capitalized tag name)
	 */
	private String typeTagLabel(JavadocBlockTag tag) {
		switch (tag.getType()) {
			case DEPRECATED:
				return "Deprecated";
			case SEE:
				return "See";
			case PARAM:
				return "Param";
			case RETURN:
				return "Returns";
			case THROWS:
			case EXCEPTION:
				return "Throws";
			default:
				return capitalize(tag.getTagName());
		}
	}

	/**
	 * Extracts the first-sentence summary for a table Description cell.
	 *
	 * @param javadoc the member or type Javadoc
	 * @return the escaped, single-line first sentence, or empty string if undocumented
	 */
	private String summaryText(java.util.Optional<Javadoc> javadoc) {
		if (!javadoc.isPresent()) {
			return "";
		}
		String text = convertInlineTags(javadoc.get().getDescription().toText());
		text = HTML_TAG.matcher(text).replaceAll(" ");
		text = firstSentence(text).replace("\n", " ").replace("\r", " ").trim();
		text = text.replaceAll("\\s+", " ");
		return text.replace("|", "\\|");
	}

	/**
	 * Returns the first sentence of description text (up to a period at a word boundary).
	 *
	 * @param text the description text
	 * @return the first sentence, including its terminating period
	 */
	private String firstSentence(String text) {
		for (int i = 0; i < text.length(); i++) {
			if (text.charAt(i) == '.') {
				boolean atEnd = i + 1 >= text.length();
				if (atEnd || Character.isWhitespace(text.charAt(i + 1))) {
					return text.substring(0, i + 1);
				}
			}
		}
		return text;
	}

	/**
	 * Wraps text in inline code for a table cell, escaping pipes.
	 *
	 * @param text the raw cell text
	 * @return the escaped inline-code cell, or an empty string when the text is blank
	 */
	private String cellCode(String text) {
		if (text.isEmpty()) {
			return "";
		}
		return "`" + text.replace("|", "\\|") + "`";
	}

	/**
	 * Converts supported inline tags to inline code, leaving other inline tags raw.
	 *
	 * @param text the raw description or content text
	 * @return the converted text
	 */
	private String convertInlineTags(String text) {
		Matcher matcher = INLINE_TAG.matcher(text);
		StringBuffer out = new StringBuffer();
		while (matcher.find()) {
			String inner = matcher.group(2).trim();
			matcher.appendReplacement(out, Matcher.quoteReplacement("`" + inner + "`"));
		}
		matcher.appendTail(out);
		return out.toString();
	}

	/**
	 * Capitalizes the first character of a tag name for display.
	 *
	 * @param tagName the raw tag name
	 * @return the capitalized name
	 */
	private String capitalize(String tagName) {
		if (tagName == null || tagName.isEmpty()) {
			return "";
		}
		return Character.toUpperCase(tagName.charAt(0)) + tagName.substring(1);
	}

	/**
	 * Produces a GitHub-compatible heading anchor slug.
	 *
	 * @param heading the heading text
	 * @return the anchor slug
	 */
	private String slug(String heading) {
		StringBuilder sb = new StringBuilder();
		for (char c : heading.toLowerCase().toCharArray()) {
			if (Character.isLetterOrDigit(c) && c < 128) {
				sb.append(c);
			}
			else if (c == ' ' || c == '-') {
				sb.append('-');
			}
		}
		return sb.toString();
	}

	/**
	 * Normalizes line endings to {@code \n} and enforces exactly one trailing newline.
	 *
	 * @param text the assembled document text
	 * @return the normalized text
	 */
	private String normalizeTrailing(String text) {
		String lf = text.replace("\r\n", "\n").replace("\r", "\n");
		int end = lf.length();
		while (end > 0 && lf.charAt(end - 1) == '\n') {
			end--;
		}
		return lf.substring(0, end) + "\n";
	}
}

package docs;

import com.github.javaparser.JavaParser;
import com.github.javaparser.ParseResult;
import com.github.javaparser.ParserConfiguration;
import com.github.javaparser.ast.CompilationUnit;
import com.github.javaparser.ast.Modifier;
import com.github.javaparser.ast.body.AnnotationDeclaration;
import com.github.javaparser.ast.body.AnnotationMemberDeclaration;
import com.github.javaparser.ast.body.BodyDeclaration;
import com.github.javaparser.ast.body.ClassOrInterfaceDeclaration;
import com.github.javaparser.ast.body.ConstructorDeclaration;
import com.github.javaparser.ast.body.EnumConstantDeclaration;
import com.github.javaparser.ast.body.EnumDeclaration;
import com.github.javaparser.ast.body.FieldDeclaration;
import com.github.javaparser.ast.body.MethodDeclaration;
import com.github.javaparser.ast.body.Parameter;
import com.github.javaparser.ast.body.TypeDeclaration;
import com.github.javaparser.ast.body.VariableDeclarator;
import com.github.javaparser.ast.comments.Comment;
import com.github.javaparser.ast.comments.JavadocComment;
import com.github.javaparser.ast.expr.AnnotationExpr;
import com.github.javaparser.ast.nodeTypes.NodeWithModifiers;
import com.github.javaparser.javadoc.Javadoc;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.EnumSet;
import java.util.List;
import java.util.Optional;
import java.util.stream.Collectors;
import java.util.stream.Stream;

/**
 * Parses the project's Java sources into a {@link JavaDocModel.TypeDoc} list.
 *
 * <p>Only {@code src/main/java} is scanned; {@code build/}, {@code generated/}, and
 * test sources are ignored. Every type and member is captured regardless of
 * modifier, together with its parsed Javadoc (empty when undocumented).</p>
 */
public final class JavaDocScanner {

	private final Path sourceRoot;

	/**
	 * Creates a scanner rooted at the given source directory.
	 *
	 * @param sourceRoot the {@code src/main/java} directory to scan
	 */
	public JavaDocScanner(Path sourceRoot) {
		this.sourceRoot = sourceRoot;
	}

	/**
	 * Parses every source file and returns the collected type records.
	 *
	 * @return the type records, in parse order (the renderer sorts them)
	 */
	public List<JavaDocModel.TypeDoc> scan() {
		JavaParser parser = new JavaParser(
				new ParserConfiguration().setLanguageLevel(ParserConfiguration.LanguageLevel.JAVA_11));
		List<JavaDocModel.TypeDoc> out = new ArrayList<>();
		List<Path> files = sourceFiles();
		for (Path file : files) {
			CompilationUnit cu = parse(parser, file);
			String packageName = cu.getPackageDeclaration()
					.map(pd -> pd.getNameAsString())
					.orElse("");
			for (TypeDeclaration<?> type : cu.getTypes()) {
				collectType(type, packageName, out);
			}
		}
		return out;
	}

	/**
	 * Returns the {@code .java} files under the source root, excluding build output.
	 *
	 * @return the source file paths
	 */
	private List<Path> sourceFiles() {
		if (!Files.isDirectory(sourceRoot)) {
			return List.of();
		}
		try (Stream<Path> walk = Files.walk(sourceRoot)) {
			return walk
					.filter(Files::isRegularFile)
					.filter(p -> p.getFileName().toString().endsWith(".java"))
					.filter(p -> !isExcluded(p))
					.collect(Collectors.toList());
		}
		catch (IOException e) {
			throw new UncheckedIOException("Failed to walk source root " + sourceRoot, e);
		}
	}

	/**
	 * Reports whether a path lies under an excluded directory.
	 *
	 * @param path the candidate source file
	 * @return {@code true} if the file should be skipped
	 */
	private boolean isExcluded(Path path) {
		for (Path segment : path) {
			String name = segment.toString();
			if (name.equals("build") || name.equals("generated")) {
				return true;
			}
		}
		return false;
	}

	/**
	 * Parses a single source file, failing loudly on syntax errors.
	 *
	 * @param parser the configured parser
	 * @param file the file to parse
	 * @return the parsed compilation unit
	 */
	private CompilationUnit parse(JavaParser parser, Path file) {
		try {
			String content = new String(Files.readAllBytes(file), StandardCharsets.UTF_8);
			ParseResult<CompilationUnit> result = parser.parse(content);
			if (!result.isSuccessful() || !result.getResult().isPresent()) {
				throw new IllegalStateException("Failed to parse " + file + ": " + result.getProblems());
			}
			return result.getResult().get();
		}
		catch (IOException e) {
			throw new UncheckedIOException("Failed to read " + file, e);
		}
	}

	/**
	 * Records a type declaration and recurses into its nested types.
	 *
	 * @param type the type declaration
	 * @param packageName the enclosing package name
	 * @param out the accumulating result list
	 */
	private void collectType(TypeDeclaration<?> type, String packageName, List<JavaDocModel.TypeDoc> out) {
		String qualifiedName = type.getFullyQualifiedName().orElse(type.getNameAsString());
		JavaDocModel.TypeKind kind = kindOf(type);
		List<JavaDocModel.MemberDoc> fields = new ArrayList<>();
		List<JavaDocModel.MemberDoc> constructors = new ArrayList<>();
		List<JavaDocModel.MemberDoc> methods = new ArrayList<>();
		if (type instanceof EnumDeclaration) {
			for (EnumConstantDeclaration entry : ((EnumDeclaration) type).getEntries()) {
				fields.add(enumConstant(entry));
			}
		}
		for (FieldDeclaration field : type.getFields()) {
			for (VariableDeclarator variable : field.getVariables()) {
				fields.add(fieldMember(field, variable));
			}
		}
		for (ConstructorDeclaration ctor : type.getConstructors()) {
			constructors.add(constructorMember(ctor));
		}
		for (MethodDeclaration method : type.getMethods()) {
			methods.add(methodMember(method));
		}
		for (BodyDeclaration<?> member : type.getMembers()) {
			if (member instanceof AnnotationMemberDeclaration) {
				methods.add(annotationMember((AnnotationMemberDeclaration) member));
			}
		}
		out.add(new JavaDocModel.TypeDoc(
				packageName,
				qualifiedName,
				type.getNameAsString(),
				kind,
				typeSignature(type, kind),
				modifiersOf(type),
				javadocOf(type),
				fields,
				constructors,
				methods));
		for (BodyDeclaration<?> member : type.getMembers()) {
			if (member instanceof TypeDeclaration) {
				collectType((TypeDeclaration<?>) member, packageName, out);
			}
		}
	}

	/**
	 * Determines the kind of a type declaration.
	 *
	 * @param type the type declaration
	 * @return the matching kind
	 */
	private JavaDocModel.TypeKind kindOf(TypeDeclaration<?> type) {
		if (type instanceof EnumDeclaration) {
			return JavaDocModel.TypeKind.ENUM;
		}
		if (type instanceof AnnotationDeclaration) {
			return JavaDocModel.TypeKind.ANNOTATION;
		}
		if (type instanceof ClassOrInterfaceDeclaration && ((ClassOrInterfaceDeclaration) type).isInterface()) {
			return JavaDocModel.TypeKind.INTERFACE;
		}
		return JavaDocModel.TypeKind.CLASS;
	}

	/**
	 * Builds the display signature for a type declaration.
	 *
	 * @param type the type declaration
	 * @param kind the resolved type kind
	 * @return the declaration line
	 */
	private String typeSignature(TypeDeclaration<?> type, JavaDocModel.TypeKind kind) {
		StringBuilder sb = new StringBuilder();
		sb.append(modifierPrefix(type));
		sb.append(kind.label().equals("annotation") ? "@interface" : kind.label());
		sb.append(' ').append(type.getNameAsString());
		if (type instanceof ClassOrInterfaceDeclaration) {
			ClassOrInterfaceDeclaration decl = (ClassOrInterfaceDeclaration) type;
			if (!decl.getTypeParameters().isEmpty()) {
				sb.append('<')
						.append(decl.getTypeParameters().stream()
								.map(tp -> tp.asString())
								.collect(Collectors.joining(", ")))
						.append('>');
			}
		}
		return sb.toString();
	}

	/**
	 * Builds a member record for an enum constant.
	 *
	 * @param entry the enum constant declaration
	 * @return the member record
	 */
	private JavaDocModel.MemberDoc enumConstant(EnumConstantDeclaration entry) {
		return new JavaDocModel.MemberDoc(
				JavaDocModel.MemberKind.ENUM_CONSTANT,
				entry.getNameAsString(),
				"",
				entry.getNameAsString(),
				List.of(),
				EnumSet.noneOf(Modifier.Keyword.class),
				false,
				javadocOf(entry));
	}

	/**
	 * Builds a member record for one field variable.
	 *
	 * @param field the field declaration (holds modifiers and Javadoc)
	 * @param variable the individual variable declarator
	 * @return the member record
	 */
	private JavaDocModel.MemberDoc fieldMember(FieldDeclaration field, VariableDeclarator variable) {
		String modifierAndType = (modifierPrefix(field) + variable.getTypeAsString()).trim();
		return new JavaDocModel.MemberDoc(
				JavaDocModel.MemberKind.FIELD,
				variable.getNameAsString(),
				modifierAndType,
				variable.getNameAsString(),
				List.of(),
				modifiersOf(field),
				false,
				javadocOf(field));
	}

	/**
	 * Builds a member record for a constructor.
	 *
	 * @param ctor the constructor declaration
	 * @return the member record
	 */
	private JavaDocModel.MemberDoc constructorMember(ConstructorDeclaration ctor) {
		String modifierAndType = (modifierPrefix(ctor) + typeParameterPrefix(ctor.getTypeParameters())).trim();
		StringBuilder declaration = new StringBuilder();
		declaration.append(ctor.getNameAsString());
		declaration.append('(').append(parameterList(ctor.getParameters())).append(')');
		declaration.append(throwsSuffix(ctor.getThrownExceptions().stream()
				.map(t -> t.asString())
				.collect(Collectors.toList())));
		return new JavaDocModel.MemberDoc(
				JavaDocModel.MemberKind.CONSTRUCTOR,
				ctor.getNameAsString(),
				modifierAndType,
				declaration.toString(),
				paramSimpleNames(ctor.getParameters()),
				modifiersOf(ctor),
				false,
				javadocOf(ctor));
	}

	/**
	 * Builds a member record for a method.
	 *
	 * @param method the method declaration
	 * @return the member record
	 */
	private JavaDocModel.MemberDoc methodMember(MethodDeclaration method) {
		String modifierAndType = (modifierPrefix(method)
				+ typeParameterPrefix(method.getTypeParameters())
				+ method.getTypeAsString()).trim();
		StringBuilder declaration = new StringBuilder();
		declaration.append(method.getNameAsString());
		declaration.append('(').append(parameterList(method.getParameters())).append(')');
		declaration.append(throwsSuffix(method.getThrownExceptions().stream()
				.map(t -> t.asString())
				.collect(Collectors.toList())));
		return new JavaDocModel.MemberDoc(
				JavaDocModel.MemberKind.METHOD,
				method.getNameAsString(),
				modifierAndType,
				declaration.toString(),
				paramSimpleNames(method.getParameters()),
				modifiersOf(method),
				method.getAnnotationByName("Override").isPresent(),
				javadocOf(method));
	}

	/**
	 * Builds a member record for an annotation element.
	 *
	 * @param member the annotation member declaration
	 * @return the member record
	 */
	private JavaDocModel.MemberDoc annotationMember(AnnotationMemberDeclaration member) {
		String modifierAndType = (modifierPrefix(member) + member.getTypeAsString()).trim();
		return new JavaDocModel.MemberDoc(
				JavaDocModel.MemberKind.METHOD,
				member.getNameAsString(),
				modifierAndType,
				member.getNameAsString() + "()",
				List.of(),
				modifiersOf(member),
				false,
				javadocOf(member));
	}

	/**
	 * Renders a parameter list as {@code Type name} pairs.
	 *
	 * @param parameters the parameters
	 * @return the comma-separated parameter text
	 */
	private String parameterList(List<Parameter> parameters) {
		return parameters.stream()
				.map(p -> paramType(p) + " " + p.getNameAsString())
				.collect(Collectors.joining(", "));
	}

	/**
	 * Renders a parameter's declared type, expanding varargs to {@code ...}.
	 *
	 * @param parameter the parameter
	 * @return the type text
	 */
	private String paramType(Parameter parameter) {
		String type = parameter.getType().asString();
		return parameter.isVarArgs() ? type + "..." : type;
	}

	/**
	 * Computes the overload-disambiguating simple type names for a parameter list.
	 *
	 * @param parameters the parameters
	 * @return the erased simple type names
	 */
	private List<String> paramSimpleNames(List<Parameter> parameters) {
		return parameters.stream()
				.map(p -> simpleTypeName(p.getType().asString()) + (p.isVarArgs() ? "[]" : ""))
				.collect(Collectors.toList());
	}

	/**
	 * Reduces a possibly-qualified, generic type string to a stable simple name.
	 *
	 * @param type the raw type string
	 * @return the simple type name with generics stripped and package removed
	 */
	private String simpleTypeName(String type) {
		StringBuilder sb = new StringBuilder();
		int depth = 0;
		for (int i = 0; i < type.length(); i++) {
			char c = type.charAt(i);
			if (c == '<') {
				depth++;
			}
			else if (c == '>') {
				depth--;
			}
			else if (depth == 0) {
				sb.append(c);
			}
		}
		String stripped = sb.toString().trim();
		int dot = stripped.lastIndexOf('.');
		return dot >= 0 ? stripped.substring(dot + 1) : stripped;
	}

	/**
	 * Renders method or constructor type parameters as a {@code <T, U> } prefix.
	 *
	 * @param typeParameters the type parameters
	 * @return the prefix, or empty string when there are none
	 */
	private String typeParameterPrefix(List<com.github.javaparser.ast.type.TypeParameter> typeParameters) {
		if (typeParameters.isEmpty()) {
			return "";
		}
		return "<" + typeParameters.stream()
				.map(tp -> tp.asString())
				.collect(Collectors.joining(", ")) + "> ";
	}

	/**
	 * Renders a {@code throws} suffix from exception type names.
	 *
	 * @param thrown the thrown exception type strings
	 * @return the suffix, or empty string when nothing is thrown
	 */
	private String throwsSuffix(List<String> thrown) {
		if (thrown.isEmpty()) {
			return "";
		}
		return " throws " + String.join(", ", thrown);
	}

	/**
	 * Renders a node's modifiers as a trailing-spaced prefix.
	 *
	 * @param node the modifier-bearing node
	 * @return the modifier text ending in a space, or empty string when none
	 */
	private String modifierPrefix(NodeWithModifiers<?> node) {
		String mods = node.getModifiers().stream()
				.map(m -> m.getKeyword().asString())
				.collect(Collectors.joining(" "));
		return mods.isEmpty() ? "" : mods + " ";
	}

	/**
	 * Resolves a declaration's Javadoc, recovering a comment that JavaParser attached
	 * to a leading annotation when the Javadoc sits between annotations rather than above them.
	 *
	 * @param node the declaration
	 * @return the parsed Javadoc, or empty if the declaration is undocumented
	 */
	private Optional<Javadoc> javadocOf(BodyDeclaration<?> node) {
		Optional<Javadoc> direct = parseJavadoc(node.getComment().orElse(null));
		if (direct.isPresent()) {
			return direct;
		}
		for (AnnotationExpr annotation : node.getAnnotations()) {
			Optional<Javadoc> onAnnotation = parseJavadoc(annotation.getComment().orElse(null));
			if (onAnnotation.isPresent()) {
				return onAnnotation;
			}
		}
		return Optional.empty();
	}

	/**
	 * Parses a comment into a {@link Javadoc}, or returns empty when it is not a Javadoc comment.
	 *
	 * @param comment the comment to parse, may be {@code null}
	 * @return the parsed Javadoc, or empty
	 */
	private Optional<Javadoc> parseJavadoc(Comment comment) {
		if (comment instanceof JavadocComment) {
			return Optional.of(((JavadocComment) comment).parse());
		}
		return Optional.empty();
	}

	/**
	 * Collects a node's modifier keywords into an {@link EnumSet}.
	 *
	 * @param node the modifier-bearing node
	 * @return the modifier keyword set
	 */
	private EnumSet<Modifier.Keyword> modifiersOf(NodeWithModifiers<?> node) {
		EnumSet<Modifier.Keyword> set = EnumSet.noneOf(Modifier.Keyword.class);
		for (Modifier modifier : node.getModifiers()) {
			set.add(modifier.getKeyword());
		}
		return set;
	}
}

package docs;

import com.github.javaparser.ast.Modifier;
import com.github.javaparser.javadoc.Javadoc;
import java.util.EnumSet;
import java.util.List;
import java.util.Optional;

/**
 * Immutable data holders describing the documented shape of the source tree.
 *
 * <p>The scanner populates these, the renderer turns them into Markdown, and the
 * coverage checker inspects them for missing public/protected documentation.</p>
 */
public final class JavaDocModel {

	private JavaDocModel() {
	}

	/**
	 * The kind of a type declaration.
	 */
	public enum TypeKind {
		/** A {@code class} declaration. */
		CLASS("class"),
		/** An {@code interface} declaration. */
		INTERFACE("interface"),
		/** An {@code enum} declaration. */
		ENUM("enum"),
		/** An {@code @interface} (annotation) declaration. */
		ANNOTATION("annotation");

		private final String label;

		TypeKind(String label) {
			this.label = label;
		}

		/**
		 * Returns the lowercase label rendered in the Markdown output.
		 *
		 * @return the display label
		 */
		public String label() {
			return label;
		}
	}

	/**
	 * The kind of a member declaration.
	 */
	public enum MemberKind {
		/** A field declaration. */
		FIELD,
		/** An enum constant. */
		ENUM_CONSTANT,
		/** A constructor declaration. */
		CONSTRUCTOR,
		/** A method declaration. */
		METHOD
	}

	/**
	 * A documented type declaration, including its members.
	 */
	public static final class TypeDoc {

		private final String packageName;
		private final String qualifiedName;
		private final String simpleName;
		private final TypeKind kind;
		private final String signature;
		private final EnumSet<Modifier.Keyword> modifiers;
		private final Optional<Javadoc> javadoc;
		private final List<MemberDoc> fields;
		private final List<MemberDoc> constructors;
		private final List<MemberDoc> methods;

		/**
		 * Creates a type record.
		 *
		 * @param packageName the package name, or empty string for the default package
		 * @param qualifiedName the fully-qualified name, with nested types joined by {@code .}
		 * @param simpleName the simple (unqualified) name
		 * @param kind the type kind
		 * @param signature the human-readable declaration line
		 * @param modifiers the declared modifiers
		 * @param javadoc the parsed Javadoc, or empty if undocumented
		 * @param fields the field and enum-constant members
		 * @param constructors the constructor members
		 * @param methods the method members
		 */
		public TypeDoc(
				String packageName,
				String qualifiedName,
				String simpleName,
				TypeKind kind,
				String signature,
				EnumSet<Modifier.Keyword> modifiers,
				Optional<Javadoc> javadoc,
				List<MemberDoc> fields,
				List<MemberDoc> constructors,
				List<MemberDoc> methods) {
			this.packageName = packageName;
			this.qualifiedName = qualifiedName;
			this.simpleName = simpleName;
			this.kind = kind;
			this.signature = signature;
			this.modifiers = modifiers;
			this.javadoc = javadoc;
			this.fields = fields;
			this.constructors = constructors;
			this.methods = methods;
		}

		/**
		 * Returns the package name.
		 *
		 * @return the package name, or empty string for the default package
		 */
		public String packageName() {
			return packageName;
		}

		/**
		 * Returns the fully-qualified name.
		 *
		 * @return the fully-qualified name
		 */
		public String qualifiedName() {
			return qualifiedName;
		}

		/**
		 * Returns the simple name.
		 *
		 * @return the simple name
		 */
		public String simpleName() {
			return simpleName;
		}

		/**
		 * Returns the type kind.
		 *
		 * @return the type kind
		 */
		public TypeKind kind() {
			return kind;
		}

		/**
		 * Returns the human-readable declaration line.
		 *
		 * @return the declaration signature
		 */
		public String signature() {
			return signature;
		}

		/**
		 * Returns the declared modifiers.
		 *
		 * @return the modifier keywords
		 */
		public EnumSet<Modifier.Keyword> modifiers() {
			return modifiers;
		}

		/**
		 * Returns the parsed Javadoc, if present.
		 *
		 * @return the Javadoc, or empty if undocumented
		 */
		public Optional<Javadoc> javadoc() {
			return javadoc;
		}

		/**
		 * Returns the field and enum-constant members.
		 *
		 * @return the fields
		 */
		public List<MemberDoc> fields() {
			return fields;
		}

		/**
		 * Returns the constructor members.
		 *
		 * @return the constructors
		 */
		public List<MemberDoc> constructors() {
			return constructors;
		}

		/**
		 * Returns the method members.
		 *
		 * @return the methods
		 */
		public List<MemberDoc> methods() {
			return methods;
		}
	}

	/**
	 * A documented member declaration (field, enum constant, constructor, or method).
	 */
	public static final class MemberDoc {

		private final MemberKind kind;
		private final String name;
		private final String modifierAndType;
		private final String declaration;
		private final String signature;
		private final List<String> paramTypeSimpleNames;
		private final EnumSet<Modifier.Keyword> modifiers;
		private final boolean overrides;
		private final Optional<Javadoc> javadoc;

		/**
		 * Creates a member record.
		 *
		 * @param kind the member kind
		 * @param name the member name
		 * @param modifierAndType the modifier-and-type prefix shown in summary tables (may be empty)
		 * @param declaration the name-and-parameters portion shown in summary tables
		 * @param paramTypeSimpleNames the parameter type simple names, used to disambiguate overloads
		 * @param modifiers the declared modifiers
		 * @param overrides whether the member carries an {@code @Override} annotation
		 * @param javadoc the parsed Javadoc, or empty if undocumented
		 */
		public MemberDoc(
				MemberKind kind,
				String name,
				String modifierAndType,
				String declaration,
				List<String> paramTypeSimpleNames,
				EnumSet<Modifier.Keyword> modifiers,
				boolean overrides,
				Optional<Javadoc> javadoc) {
			this.kind = kind;
			this.name = name;
			this.modifierAndType = modifierAndType;
			this.declaration = declaration;
			this.signature = (modifierAndType + " " + declaration).trim();
			this.paramTypeSimpleNames = paramTypeSimpleNames;
			this.modifiers = modifiers;
			this.overrides = overrides;
			this.javadoc = javadoc;
		}

		/**
		 * Returns the member kind.
		 *
		 * @return the member kind
		 */
		public MemberKind kind() {
			return kind;
		}

		/**
		 * Returns the member name.
		 *
		 * @return the member name
		 */
		public String name() {
			return name;
		}

		/**
		 * Returns the modifier-and-type prefix used in summary tables.
		 *
		 * @return the modifier-and-type text, possibly empty
		 */
		public String modifierAndType() {
			return modifierAndType;
		}

		/**
		 * Returns the name-and-parameters portion used in summary tables.
		 *
		 * @return the declaration text
		 */
		public String declaration() {
			return declaration;
		}

		/**
		 * Returns the full human-readable declaration line.
		 *
		 * @return the declaration signature
		 */
		public String signature() {
			return signature;
		}

		/**
		 * Returns the parameter type simple names.
		 *
		 * @return the parameter type simple names
		 */
		public List<String> paramTypeSimpleNames() {
			return paramTypeSimpleNames;
		}

		/**
		 * Returns the declared modifiers.
		 *
		 * @return the modifier keywords
		 */
		public EnumSet<Modifier.Keyword> modifiers() {
			return modifiers;
		}

		/**
		 * Returns whether the member is annotated {@code @Override}.
		 *
		 * @return {@code true} if the member overrides a supertype member
		 */
		public boolean overrides() {
			return overrides;
		}

		/**
		 * Returns the parsed Javadoc, if present.
		 *
		 * @return the Javadoc, or empty if undocumented
		 */
		public Optional<Javadoc> javadoc() {
			return javadoc;
		}
	}
}

package docs;

import com.github.javaparser.ast.Modifier;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Finds public and protected declarations that are missing Javadoc.
 *
 * <p>Package-private and private declarations are never flagged. Interface and
 * annotation members, and enum constants, are treated as effectively public
 * unless explicitly marked {@code private}. {@code @Override} methods are
 * required to be documented by default; pass {@code excludeOverrides} to skip
 * them.</p>
 */
public final class CoverageChecker {

	private final boolean excludeOverrides;

	private final Map<String, JavaDocModel.TypeDoc> byQualifiedName = new HashMap<>();

	private final Map<String, Boolean> visibilityCache = new HashMap<>();

	/**
	 * Creates a checker.
	 *
	 * @param excludeOverrides whether {@code @Override} methods are exempt from the requirement
	 */
	public CoverageChecker(boolean excludeOverrides) {
		this.excludeOverrides = excludeOverrides;
	}

	/**
	 * Returns the sorted list of undocumented public/protected offenders.
	 *
	 * <p>A declaration is in scope only when it is public/protected <em>and</em> every
	 * enclosing type is itself externally reachable; members of a package-private (or
	 * private) type are never flagged, matching the "public + protected only" scope.</p>
	 *
	 * @param types the scanned type records
	 * @return the offender identifiers, sorted
	 */
	public List<String> findOffenders(List<JavaDocModel.TypeDoc> types) {
		byQualifiedName.clear();
		visibilityCache.clear();
		for (JavaDocModel.TypeDoc type : types) {
			byQualifiedName.put(type.qualifiedName(), type);
		}
		List<String> offenders = new ArrayList<>();
		for (JavaDocModel.TypeDoc type : types) {
			if (!typeExternallyVisible(type)) {
				continue;
			}
			if (!type.javadoc().isPresent()) {
				offenders.add(type.qualifiedName() + " (type)");
			}
			collectMembers(type, type.fields(), offenders);
			collectMembers(type, type.constructors(), offenders);
			collectMembers(type, type.methods(), offenders);
		}
		offenders.sort(String::compareTo);
		return offenders;
	}

	/**
	 * Reports whether a type is reachable as external API (it and every enclosing type
	 * are public/protected, with interface and annotation members implicitly public).
	 *
	 * @param type the type record
	 * @return {@code true} if the type is externally reachable
	 */
	private boolean typeExternallyVisible(JavaDocModel.TypeDoc type) {
		Boolean cached = visibilityCache.get(type.qualifiedName());
		if (cached != null) {
			return cached;
		}
		JavaDocModel.TypeDoc enclosing = enclosingType(type);
		boolean visibleHere;
		if (enclosing != null
				&& (enclosing.kind() == JavaDocModel.TypeKind.INTERFACE
				|| enclosing.kind() == JavaDocModel.TypeKind.ANNOTATION)) {
			visibleHere = true;
		}
		else {
			visibleHere = type.modifiers().contains(Modifier.Keyword.PUBLIC)
					|| type.modifiers().contains(Modifier.Keyword.PROTECTED);
		}
		boolean result = visibleHere && (enclosing == null || typeExternallyVisible(enclosing));
		visibilityCache.put(type.qualifiedName(), result);
		return result;
	}

	/**
	 * Finds the immediately enclosing type of a nested type, if any.
	 *
	 * @param type the type record
	 * @return the enclosing type, or {@code null} for a top-level type
	 */
	private JavaDocModel.TypeDoc enclosingType(JavaDocModel.TypeDoc type) {
		String qualifiedName = type.qualifiedName();
		int lastDot = qualifiedName.lastIndexOf('.');
		if (lastDot < 0) {
			return null;
		}
		return byQualifiedName.get(qualifiedName.substring(0, lastDot));
	}

	/**
	 * Flags undocumented members that require documentation.
	 *
	 * @param type the enclosing type
	 * @param members the members to inspect
	 * @param offenders the accumulating offender list
	 */
	private void collectMembers(
			JavaDocModel.TypeDoc type,
			List<JavaDocModel.MemberDoc> members,
			List<String> offenders) {
		for (JavaDocModel.MemberDoc member : members) {
			if (!requiresDoc(type, member)) {
				continue;
			}
			if (member.javadoc().isPresent()) {
				continue;
			}
			offenders.add(memberId(type, member));
		}
	}

	/**
	 * Reports whether a member requires documentation under the gate rules.
	 *
	 * @param type the enclosing type
	 * @param member the member record
	 * @return {@code true} if the member is in scope and not exempt
	 */
	private boolean requiresDoc(JavaDocModel.TypeDoc type, JavaDocModel.MemberDoc member) {
		if (excludeOverrides && member.overrides()) {
			return false;
		}
		return isEffectivelyPublicOrProtected(type, member);
	}

	/**
	 * Computes a member's effective visibility, accounting for implicit-public contexts.
	 *
	 * @param type the enclosing type
	 * @param member the member record
	 * @return {@code true} if the member is effectively public or protected
	 */
	private boolean isEffectivelyPublicOrProtected(JavaDocModel.TypeDoc type, JavaDocModel.MemberDoc member) {
		if (member.kind() == JavaDocModel.MemberKind.ENUM_CONSTANT) {
			return true;
		}
		if (member.modifiers().contains(Modifier.Keyword.PUBLIC)
				|| member.modifiers().contains(Modifier.Keyword.PROTECTED)) {
			return true;
		}
		boolean implicitlyPublicContext = type.kind() == JavaDocModel.TypeKind.INTERFACE
				|| type.kind() == JavaDocModel.TypeKind.ANNOTATION;
		return implicitlyPublicContext && !member.modifiers().contains(Modifier.Keyword.PRIVATE);
	}

	/**
	 * Builds the stable offender identifier for a member.
	 *
	 * @param type the enclosing type
	 * @param member the member record
	 * @return the identifier, e.g. {@code com.example.Foo#increment(int)}
	 */
	private String memberId(JavaDocModel.TypeDoc type, JavaDocModel.MemberDoc member) {
		if (member.kind() == JavaDocModel.MemberKind.METHOD
				|| member.kind() == JavaDocModel.MemberKind.CONSTRUCTOR) {
			return type.qualifiedName() + "#" + member.name()
					+ "(" + String.join(", ", member.paramTypeSimpleNames()) + ")";
		}
		return type.qualifiedName() + "#" + member.name();
	}
}
